questionvariables.text:
/* Number of blades */
blades_list : [3,4,5,6];
blades : blades_list[rand(length(blades_list))+1];

/* Number of complete revolutions */
rev : rand(3)+1;

/* Total time (minutes) */
total_time : rand(4)+2;   /* 3-6 minutes */

/* Elapsed time */
elapsed : rand(total_time-1)+1;

/* Teacher answers */
angle : 360*rev*elapsed/total_time;
blade_angle : 360/blades;
order : blades;

/* Candidate letters. The centre of rotation is A at [0,0] in the
   diagram, so A is the correct option; perm only shuffles the ORDER
   in which the letters are offered. */
letters : ["A","B","C","D"];
perm    : random_permutation(letters);
centre  : "A";

/* (a)-(c): typed numerical answers */
ta1 : angle;
ta2 : blade_angle;
ta3 : order;

/* (d) dropdown: rotation is an isometry - size and shape are unchanged.
   Distractors are the real misconceptions (confusing rotation with
   enlargement / a shape-changing transformation). */
ta4 : [[1, true,  "No - both size and shape stay the same"],
       [2, false, "Yes - the size changes"],
       [3, false, "Yes - the shape changes"],
       [4, false, "Yes - both the size and the shape change"]];

/* (e) dropdown: which labelled point is the centre of rotation?
   Options are built from perm, so the letters appear in a random
   order, and the one equal to `centre` is flagged correct. */
ta5 : makelist([k, is(perm[k] = centre), sconcat("Point ", perm[k])],
                k, 1, length(perm));
/* The correct VALUE for each dropdown - what the PRT compares against.
   ta4/ta5 stay as the option lists for the inputs. */
ta4v : 1;

/* For (e), find which position holds the correct letter. */
ta5v : first(sublist_indices(perm, lambda([z], is(z = centre))));
